cat >> index.html <<'EOF'

// ---------- per-run state ----------
let world = null, eq = null, R = null;
const runGroup = new THREE.Group(); scene.add(runGroup);
const owners = new Map();
const QI = { x:0, y:0, z:0, w:1 };
const qz = a => ({ x:0, y:0, z:Math.sin(a / 2), w:Math.cos(a / 2) });
const QX90 = { x:Math.SQRT1_2, y:0, z:0, w:Math.SQRT1_2 };
const AX = { x:1, y:0, z:0 }, AY = { x:0, y:1, z:0 }, AZ = { x:0, y:0, z:1 };
const ZAXIS = new THREE.Vector3(0, 0, 1);
const EV = RAPIER.ActiveEvents.CONTACT_FORCE_EVENTS;
const WR = 0.33, WW = 0.12;

function track(body, obj, brick) {
  const t = body.translation(), q = body.rotation();
  const o = { body, obj, brick, p0:new THREE.Vector3(t.x, t.y, t.z), q0:new THREE.Quaternion(q.x, q.y, q.z, q.w) };
  o.p1 = o.p0.clone(); o.q1 = o.q0.clone();
  R.tracked.push(o); return o;
}
function shadowed(m) { m.castShadow = true; m.receiveShadow = true; return m; }
function geoBox(w, h, d, rounded) {
  const r = Math.min(0.035, Math.min(w, h, d) * 0.45);
  const g = rounded && r > 0.004 ? new RoundedBoxGeometry(w, h, d, 2, r) : new THREE.BoxGeometry(w, h, d);
  R.geos.push(g); return g;
}

// ---------- car template (default 4.2 x 1.8 x 1.45 m, scaled per axis) ----------
function carSpec() {
  const box = (x0, x1, y0, y1, z0, z1, m = 'paint') => ({ c:[(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2], h:[Math.abs(x1 - x0) / 2, Math.abs(y1 - y0) / 2, Math.abs(z1 - z0) / 2], m });
  const slab = (a, b, z, t, hz, m = 'paint') => ({ a, b, z, t, hz, m });
  const P = [];
  const cabin = { name:'cabin', frac:0, boxes:[
    box(-1.95, 0.98, 0.28, 0.80, -0.62, 0.62, 'interior'),
    box(-0.78, 0.42, 1.37, 1.45, -0.72, 0.72),
    box(0.86, 0.98, 0.80, 0.93, -0.62, 0.62, 'dark'),
    box(-1.97, -1.93, 0.60, 0.88, -0.63, 0.63),
    box(-1.30, -1.16, 0.80, 0.94, -0.63, 0.63)
  ], deco:[
    box(0.52, 0.88, 0.80, 0.99, -0.60, 0.60, 'interior'),
    box(-0.30, 0.06, 0.80, 1.22, -0.55, -0.12, 'interior'), box(-0.30, 0.06, 0.80, 1.22, 0.12, 0.55, 'interior'),
    box(-1.10, -0.80, 0.80, 1.18, -0.58, 0.58, 'interior')
  ] };
  for (const s of [-1, 1]) {
    cabin.boxes.push(
      slab([0.93, 0.93], [0.45, 1.37], s * 0.70, 0.03, 0.035),
      box(0.00, 0.07, 0.92, 1.37, s * 0.665, s * 0.735),
      slab([-0.78, 1.37], [-1.20, 0.94], s * 0.70, 0.03, 0.035),
      box(-1.97, -1.66, 0.34, 0.93, s * 0.63, s * 0.88),
      box(-1.66, -0.94, 0.70, 0.93, s * 0.63, s * 0.88),
      box(-0.94, 0.98, 0.25, 0.335, s * 0.62, s * 0.85, 'dark'));
    cabin.deco.push(box(-1.985, -1.965, 0.70, 0.84, s * 0.50, s * 0.84, 'tail'));
  }
  P.push(cabin);
  const engine = { name:'engine', frac:0.16, front:true, boxes:[box(1.00, 1.60, 0.28, 0.80, -0.62, 0.62, 'dark')] };
  const nose = { name:'nose', frac:0.05, front:true, boxes:[box(1.62, 1.94, 0.28, 0.80, -0.62, 0.62)], deco:[box(1.94, 1.955, 0.62, 0.76, -0.36, 0.36, 'grille')] };
  for (const s of [-1, 1]) {
    engine.boxes.push(box(1.00, 1.60, 0.70, 0.86, s * 0.63, s * 0.88));
    nose.boxes.push(box(1.62, 1.94, 0.70, 0.82, s * 0.63, s * 0.88), box(1.71, 1.94, 0.34, 0.70, s * 0.63, s * 0.88));
    nose.deco.push(box(1.935, 1.955, 0.66, 0.78, s * 0.42, s * 0.80, 'head'));
  }
  P.push(engine, nose);
  P.push({ name:'bumperF', frac:0.012, front:true, boxes:[box(1.96, 2.10, 0.30, 0.60, -0.88, 0.88)], deco:[box(2.10, 2.106, 0.36, 0.48, -0.5, 0.5, 'grille')] });
  P.push({ name:'bumperR', frac:0.012, boxes:[box(-2.10, -1.97, 0.30, 0.60, -0.88, 0.88)] });
  P.push({ name:'hoodR', frac:0.012, boxes:[slab([1.00, 0.885], [1.47, 0.91], 0, 0.015, 0.88)] });
  P.push({ name:'hoodF', frac:0.012, front:true, boxes:[slab([1.47, 0.91], [1.95, 0.855], 0, 0.015, 0.88)] });
  P.push({ name:'trunk', frac:0.012, boxes:[box(-2.02, -1.30, 0.88, 0.94, -0.87, 0.87)] });
  for (const [n, x0, x1, s] of [['dFL', 0.07, 0.94, -1], ['dFR', 0.07, 0.94, 1], ['dRL', -0.86, 0.01, -1], ['dRR', -0.86, 0.01, 1]]) {
    const d = { name:n, frac:0.02, boxes:[box(x0, x1, 0.34, 0.93, s * 0.795, s * 0.885)], deco:[box(x0 + 0.08, x0 + 0.22, 0.80, 0.83, s * 0.885, s * 0.9, 'chrome')] };
    if (x1 > 0.5) d.deco.push(box(0.80, 0.92, 0.95, 1.05, s * 0.885, s * 1.0, 'dark'));
    P.push(d);
  }
  P.push({ name:'glassF', frac:0.01, glass:{ grid:[3, 4] }, boxes:[slab([0.93, 0.94], [0.45, 1.37], 0, 0.006, 0.64, 'glass')] });
  P.push({ name:'glassR', frac:0.008, glass:{ grid:[2, 4] }, boxes:[slab([-0.78, 1.37], [-1.20, 0.94], 0, 0.006, 0.64, 'glass')] });
  for (const s of [-1, 1]) {
    P.push({ name:'glassSF' + s, frac:0.004, glass:{ grid:[3, 2], trap:{ y0:0.94, y1:1.34, b0:0.08, b1:0.90, t0:0.08, t1:0.47 } }, boxes:[box(0.08, 0.72, 0.94, 1.34, s * 0.754, s * 0.766, 'glass')] });
    P.push({ name:'glassSR' + s, frac:0.004, glass:{ grid:[3, 2], trap:{ y0:0.94, y1:1.34, b0:-1.16, b1:0.00, t0:-0.80, t1:0.00 } }, boxes:[box(-0.98, 0.00, 0.94, 1.34, s * 0.754, s * 0.766, 'glass')] });
  }
  for (const [n, x, z] of [['wFL', 1.35, -0.76], ['wFR', 1.35, 0.76], ['wRL', -1.30, -0.76], ['wRR', -1.30, 0.76]])
    P.push({ name:n, frac:0.02, wheel:true, at:[x, WR, z], boxes:[] });
  let used = 0; for (const p of P) used += p.frac;
  cabin.frac = 1 - used;
  return P;
}

function wheelGeos(r, hw) {
  const tire = new THREE.CylinderGeometry(r, r, 2 * hw, 32, 1); tire.rotateX(Math.PI / 2);
  const disc = new THREE.CylinderGeometry(r * 0.66, r * 0.66, 2 * hw + 0.01, 24, 1); disc.rotateX(Math.PI / 2);
  const bits = [];
  for (const s of [-1, 1]) {
    for (let k = 0; k < 5; k++) { const b = new THREE.BoxGeometry(r * 0.13, r * 0.56, 0.02); b.translate(0, r * 0.3, 0); b.rotateZ(k * Math.PI * 2 / 5); b.translate(0, 0, s * (hw + 0.012)); bits.push(b); }
    const hub = new THREE.CylinderGeometry(r * 0.16, r * 0.16, 0.03, 16); hub.rotateX(Math.PI / 2); hub.translate(0, 0, s * (hw + 0.015)); bits.push(hub);
    const lip = new THREE.TorusGeometry(r * 0.64, 0.012, 6, 32); lip.translate(0, 0, s * (hw + 0.006)); bits.push(lip);
  }
  const spokes = mergeGeometries(bits);
  R.geos.push(tire, disc, spokes);
  return { tire, disc, spokes };
}

function makePart(sp, M) {
  const { sx, sy, sz } = R;
  const p = { name:sp.name, spec:sp, front:!!sp.front, wheel:!!sp.wheel, metal:!sp.glass && !sp.wheel, glass:null, kids:[], joints:[], handles:[],
    contact:0, inertial:0, mass:sp.frac * M, detached:false, removed:false, pv:new THREE.Vector3(), group:new THREE.Group(), sparkT:-1, skidLast:null };
  const cols = [];
  if (sp.wheel) {
    const r = WR * sy, hw = WW * sz; p.r = r; p.hw = hw;
    cols.push({ c:[sp.at[0] * sx, sp.at[1] * sy, sp.at[2] * sz], cyl:true, r, hw, h:[r, r, hw], ang:0, vol:Math.PI * r * r * hw });
  }
  for (const b of sp.boxes) {
    let c, h, ang = 0;
    if (b.a) {
      const ax = b.a[0] * sx, ay = b.a[1] * sy, bx = b.b[0] * sx, by = b.b[1] * sy;
      c = [(ax + bx) / 2, (ay + by) / 2, b.z * sz]; ang = Math.atan2(by - ay, bx - ax);
      h = [Math.hypot(bx - ax, by - ay) / 2, b.t * Math.min(sx, sy), b.hz * sz];
    } else { c = [b.c[0] * sx, b.c[1] * sy, b.c[2] * sz]; h = [b.h[0] * sx, b.h[1] * sy, b.h[2] * sz]; }
    cols.push({ c, h, ang, m:b.m, vol:h[0] * h[1] * h[2] });
  }
  let vt = 0, ox = 0, oy = 0, oz = 0;
  for (const k of cols) { vt += k.vol; ox += k.c[0] * k.vol; oy += k.c[1] * k.vol; oz += k.c[2] * k.vol; }
  ox /= vt; oy /= vt; oz /= vt;
  p.o = { x:R.X0 + ox, y:oy, z:oz };
  const body = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(p.o.x, p.o.y, p.o.z).setCcdEnabled(true));
  p.body = body;
  let fx = 0.05, fy = 0.05, fz = 0.05;
  for (const k of cols) {
    const lx = k.c[0] - ox, ly = k.c[1] - oy, lz = k.c[2] - oz;
    const desc = k.cyl ? RAPIER.ColliderDesc.cylinder(k.hw, k.r).setRotation(QX90) : RAPIER.ColliderDesc.cuboid(k.h[0], k.h[1], k.h[2]).setRotation(qz(k.ang));
    desc.setTranslation(lx, ly, lz).setMass(p.mass * k.vol / vt).setFriction(sp.wheel ? 1.0 : sp.glass ? 0.4 : 0.5).setRestitution(0.12)
      .setActiveEvents(EV).setContactForceEventThreshold(300);
    const col = world.createCollider(desc, body);
    owners.set(col.handle, { k:'part', p }); p.handles.push(col.handle);
    const ca = Math.abs(Math.cos(k.ang)), sa = Math.abs(Math.sin(k.ang));
    fx = Math.max(fx, Math.abs(lx) + k.h[0] * ca + k.h[1] * sa); fy = Math.max(fy, Math.abs(ly) + k.h[0] * sa + k.h[1] * ca); fz = Math.max(fz, Math.abs(lz) + k.h[2]);
    if (k.cyl) {
      if (!R.wg) R.wg = wheelGeos(k.r, k.hw);
      p.group.add(shadowed(new THREE.Mesh(R.wg.tire, Mat.tire)), shadowed(new THREE.Mesh(R.wg.disc, Mat.dark)), shadowed(new THREE.Mesh(R.wg.spokes, Mat.chrome)));
    } else if (!(sp.glass && sp.glass.trap)) {
      const m = shadowed(new THREE.Mesh(geoBox(2 * k.h[0], 2 * k.h[1], 2 * k.h[2], k.m === 'paint'), Mat[k.m]));
      m.position.set(lx, ly, lz); m.rotation.z = k.ang; p.group.add(m);
    }
    if (sp.glass) {
      const gs = sp.glass;
      p.glass = { off:new THREE.Vector3(lx, ly, lz), h:k.h.slice(), ang:k.ang, side:!!gs.trap, grid:gs.grid, inside:null };
      if (gs.trap) {
        const T = gs.trap, X = x => x * sx - ox - lx, Y = y => y * sy - oy - ly;
        const y0 = Y(T.y0), y1 = Y(T.y1), b0 = X(T.b0), b1 = X(T.b1), t0 = X(T.t0), t1 = X(T.t1);
        const shape = new THREE.Shape([new THREE.Vector2(b0, y0), new THREE.Vector2(b1, y0), new THREE.Vector2(t1, y1), new THREE.Vector2(t0, y1)]);
        const g = new THREE.ShapeGeometry(shape); R.geos.push(g);
        const m = shadowed(new THREE.Mesh(g, Mat.glass)); m.position.set(lx, ly, lz); p.group.add(m);
        p.glass.inside = (u, v) => { const t = (v - y0) / (y1 - y0); return u >= b0 + (t0 - b0) * t - 0.02 && u <= b1 + (t1 - b1) * t + 0.02; };
      }
    }
  }
  p.fx = fx; p.fy = fy; p.fz = fz;
  for (const b of sp.deco || []) {
    const m = shadowed(new THREE.Mesh(geoBox(2 * b.h[0] * sx, 2 * b.h[1] * sy, 2 * b.h[2] * sz, false), Mat[b.m]));
    m.position.set(b.c[0] * sx - ox, b.c[1] * sy - oy, b.c[2] * sz - oz); p.group.add(m);
  }
  runGroup.add(p.group);
  p.track = track(body, p.group, -1);
  R.parts.push(p);
  return p;
}

function joint(kind, a, b, pt, thr, opt = {}) {
  const P = pt.w || { x:R.X0 + pt[0] * R.sx, y:pt[1] * R.sy, z:pt[2] * R.sz };
  const a1 = { x:P.x - a.o.x, y:P.y - a.o.y, z:P.z - a.o.z }, a2 = { x:P.x - b.o.x, y:P.y - b.o.y, z:P.z - b.o.z };
  let d;
  if (kind === 'fixed') d = RAPIER.JointData.fixed(a1, QI, a2, QI);
  else if (kind === 'rev') d = RAPIER.JointData.revolute(a1, a2, opt.axis);
  else if (kind === 'sph') d = RAPIER.JointData.spherical(a1, a2);
  else { d = RAPIER.JointData.prismatic(a1, a2, AX); d.limitsEnabled = true; d.limits = [opt.lo, 0]; }
  const j = world.createImpulseJoint(d, a.body, b.body, true);
  j.setContactsEnabled(false);
  const J = { j, a, b, thr, kind, flex:opt.flex || 0, tree:opt.tree !== false, broken:false, a1, a2 };
  if (kind === 'pris') {
    Object.assign(J, { lo:opt.lo, k:opt.k, c:opt.c, Fy:opt.Fy, target:0 });
    j.configureMotorModel(RAPIER.MotorModel.ForceBased);
    j.configureMotorPosition(0, J.k, J.c);
  }
  if (J.tree) a.kids.push(J);
  a.joints.push(J); b.joints.push(J); R.joints.push(J);
  return J;
}

function buildCar() {
  R.sx = S.carL / 4.2; R.sy = S.carH / 1.45; R.sz = S.carW / 1.8;
  R.X0 = -S.trackL / 2 + S.carL / 2 + 1.5;
  const P = {};
  for (const sp of carSpec()) P[sp.name] = makePart(sp, S.mass);
  R.cabin = P.cabin; R.P = P;
  const sx = R.sx;
  joint('pris', P.cabin, P.engine, [0.99, 0.54, 0], 85e3, { lo:-0.25 * sx, k:2e6, c:4000, Fy:60e3 });
  joint('pris', P.engine, P.nose, [1.61, 0.54, 0], 55e3, { lo:-0.30 * sx, k:1e6, c:1500, Fy:35e3 });
  joint('fixed', P.nose, P.bumperF, [1.95, 0.46, 0], 14e3);
  for (const [n, par, thr] of [['wFL', P.engine, 10e3], ['wFR', P.engine, 10e3], ['wRL', P.cabin, 12e3], ['wRR', P.cabin, 12e3]])
    joint('rev', par, P[n], { w:P[n].o }, thr, { axis:AZ });
  joint('rev', P.cabin, P.hoodR, [1.00, 0.885, 0], 12e3, { axis:AZ });
  joint('rev', P.hoodR, P.hoodF, [1.47, 0.91, 0], 10e3, { axis:AZ });
  joint('sph', P.nose, P.hoodF, [1.93, 0.845, 0], 7e3, { tree:false });
  joint('rev', P.cabin, P.trunk, [-1.30, 0.91, 0], 10e3, { axis:AZ });
  joint('sph', P.cabin, P.trunk, [-2.00, 0.91, 0], 5e3, { tree:false, flex:0.025 });
  joint('fixed', P.cabin, P.bumperR, [-1.97, 0.46, 0], 14e3);
  for (const [n, hx, lx, s, th, tl] of [['dFL', 0.94, 0.07, -1, 9e3, 5e3], ['dFR', 0.94, 0.07, 1, 7.5e3, 2.5e3], ['dRL', 0.01, -0.86, -1, 6e3, 3.5e3], ['dRR', 0.01, -0.86, 1, 8e3, 4.2e3]]) {
    joint('rev', P.cabin, P[n], [hx, 0.63, s * 0.795], th, { axis:AY, flex:0.02 });
    joint('sph', P.cabin, P[n], [lx, 0.63, s * 0.795], tl, { tree:false, flex:0.035 });
  }
  joint('fixed', P.cabin, P.glassF, { w:P.glassF.o }, 2.5e3, { flex:0.06 });
  joint('fixed', P.cabin, P.glassR, { w:P.glassR.o }, 2.5e3, { flex:0.05 });
  for (const s of [-1, 1]) { joint('fixed', P.cabin, P['glassSF' + s], { w:P['glassSF' + s].o }, 2e3, { flex:0.06 }); joint('fixed', P.cabin, P['glassSR' + s], { w:P['glassSR' + s].o }, 2e3, { flex:0.055 }); }
  R.bx0 = R.X0 + 2.10 * sx;
  R.noseOff = R.bx0 - P.cabin.o.x;
  R.D = Math.max(2, R.wallFront - R.bx0);
}

function buildWall() {
  const cols = S.cols, rows = S.rows, depth = S.depth, bw = S.brickW, bh = S.brickH, bd = S.brickD;
  const x0 = R.wallX - depth * bd / 2, z0 = -cols * bw / 2;
  R.wallFront = x0; R.wallTop = rows * bh; R.wallHalfW = cols * bw / 2;
  const list = [];
  for (let l = 0; l < depth; l++) for (let r = 0; r < rows; r++) {
    const x = x0 + bd / 2 + l * bd, y = bh / 2 + r * bh;
    if ((r + l) % 2) {
      list.push([x, y, z0 + bw / 4, bw / 2]);
      for (let k = 0; k < cols - 1; k++) list.push([x, y, z0 + bw * (k + 1), bw]);
      list.push([x, y, -z0 - bw / 4, bw / 2]);
    } else for (let k = 0; k < cols; k++) list.push([x, y, z0 + bw / 2 + k * bw, bw]);
  }
  const im = new THREE.InstancedMesh(UNIT, Mat.brick, list.length);
  im.castShadow = im.receiveShadow = true; im.frustumCulled = false;
  const col = new THREE.Color();
  list.forEach(([x, y, z, w], i) => {
    const body = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(x, y, z).setCcdEnabled(true).setSleeping(true));
    const c = world.createCollider(RAPIER.ColliderDesc.cuboid(bd / 2 - 0.002, bh / 2, w / 2 - 0.002).setMass(S.brickMass * w / bw)
      .setFriction(S.brickFric).setRestitution(S.brickRest).setActiveEvents(EV).setContactForceEventThreshold(400), body);
    const b = { body, i, hy:bh / 2, fx:bd / 2, fz:w / 2, scale:new THREE.Vector3(bd - 0.012, bh - 0.012, w - 0.012) };
    owners.set(c.handle, { k:'brick', b });
    b.track = track(body, null, i);
    R.bricks.push(b);
    col.setHSL(0.012 + R.vr() * 0.03, 0.48 + R.vr() * 0.2, 0.26 + R.vr() * 0.13);
    im.setColorAt(i, col);
  });
  R.brickMesh = im; runGroup.add(im);
}

function buildRun() {
  if (world) { world.free(); eq.free(); }
  if (R) { for (const g of R.geos) g.dispose(); if (R.brickMesh) R.brickMesh.dispose(); if (R.blobs) R.blobs.dispose(); }
  runGroup.clear(); owners.clear(); resetFx();
  const L = S.trackL;
  if (envL !== L) buildEnv(L);
  world = new RAPIER.World({ x:0, y:-S.gravity, z:0 });
  world.timestep = DT;
  world.numSolverIterations = 8;
  eq = new RAPIER.EventQueue(true);
  R = { t:0, step:0, impact:false, impactT:0, impactV:0, settled:false, calm:0, shake:0, breaks:0, prng:rng(1337), vr:rng(4242),
    parts:[], joints:[], bricks:[], shards:[], tracked:[], pendingShatter:[], frontLoad:0, dustBudget:0, geos:[], wallX:L / 2 - 5, wg:null };
  const gb = world.createRigidBody(RAPIER.RigidBodyDesc.fixed());
  const gc = world.createCollider(RAPIER.ColliderDesc.cuboid(300, 1, 300).setTranslation(0, -1, 0).setFriction(S.groundFric).setRestitution(0.1), gb);
  owners.set(gc.handle, { k:'ground' });
  const bx0 = -L / 2 - 10, bx1 = L / 2 + 28;
  const stat = (hx, hy, hz, x, y, z) => { const c = world.createCollider(RAPIER.ColliderDesc.cuboid(hx, hy, hz).setTranslation(x, y, z).setFriction(0.6).setRestitution(0.2), gb); owners.set(c.handle, { k:'static' }); };
  for (const s of [1, -1]) stat((bx1 - bx0) / 2, 0.45, 0.25, (bx0 + bx1) / 2, 0.45, s * 9);
  stat(0.3, 0.5, 9.25, bx1 + 0.3, 0.5, 0);
  buildWall();
  buildCar();
  const n = R.parts.length + R.bricks.length;
  R.blobs = new THREE.InstancedMesh(BLOB_GEO, BLOB_MAT, n);
  R.blobs.geometry = BLOB_GEO.clone(); R.geos.push(R.blobs.geometry);
  R.blobOp = new THREE.InstancedBufferAttribute(new Float32Array(n), 1);
  R.blobs.geometry.setAttribute('aOp', R.blobOp);
